# =============================================================================
# DISTANCE CALCULATION (Haversine — no external libraries needed)
# =============================================================================

def haversine_miles(lat1: float, lon1: float, lat2: float, lon2: float) -> float:
    """Return great-circle distance in miles between two lat/lon points."""
    R = 3958.8  # Earth radius in miles
    phi1, phi2 = math.radians(lat1), math.radians(lat2)
    dphi = math.radians(lat2 - lat1)
    dlambda = math.radians(lon2 - lon1)
    a = math.sin(dphi / 2) ** 2 + math.cos(phi1) * math.cos(phi2) * math.sin(dlambda / 2) ** 2
    return R * 2 * math.atan2(math.sqrt(a), math.sqrt(1 - a))


# =============================================================================
# CORE MATCHING LOGIC
# =============================================================================

def find_nearby_stops(locations: List[Dict], stops: List[Dict],
                      radius_miles: float = 0.5) -> Dict[str, List[Dict]]:
    """
    For each location, return list of stops within radius_miles, sorted by distance.
    Returns: { location_name: [ {id, name, lat, lon, distance_miles}, ... ] }
    """
    results = {}
    for loc in locations:
        nearby = []
        for stop in stops:
            dist = haversine_miles(loc["lat"], loc["lon"], stop["lat"], stop["lon"])
            if dist <= radius_miles:
                nearby.append({**stop, "distance_miles": round(dist, 4)})
        nearby.sort(key=lambda s: s["distance_miles"])
        results[loc["name"]] = {
            "city": loc.get("city", ""),
            "phone": loc.get("phone", ""),
            "hours": loc.get("hours", ""),
            "lat": loc["lat"],
            "lon": loc["lon"],
            "nearby_stops": nearby,
        }
    return results


# =============================================================================
# REPORTING
# =============================================================================

def print_report(label: str, results: Dict, radius_miles: float):
    width = 72
    print(f"\n{'='*width}")
    print(f"  {label}  —  Bus stops within {radius_miles} mile(s)")
    print(f"{'='*width}")
    served = 0
    for name, data in results.items():
        stops_nearby = data["nearby_stops"]
        tag = f"📍 {name} ({data['city']})"
        if data.get("phone"):
            tag += f"  ☎ {data['phone']}"
        print(f"\n{tag}")
        if data.get("hours"):
            print(f"   🕐 {data['hours']}")
        if not stops_nearby:
            print(f"   ✗  No bus stops within {radius_miles} mile(s)")
        else:
            served += 1
            for s in stops_nearby[:8]:
                bar = "▓" * max(1, int((radius_miles - s["distance_miles"]) / radius_miles * 10))
                print(f"   🚌 {bar} [{s['id']}] {s['name']}  —  {s['distance_miles']} mi")
            if len(stops_nearby) > 8:
                print(f"   ... and {len(stops_nearby) - 8} more stop(s)")
    total = len(results)
    print(f"\n  Summary: {served}/{total} locations have ≥1 stop within {radius_miles} mile(s)")


# =============================================================================
# MAIN
# =============================================================================

def main():
    parser = argparse.ArgumentParser(description="VTA Bus Stop + Food Bank Proximity Finder")
    parser.add_argument("--radius", type=float, default=0.5,
                        help="Search radius in miles (default: 0.5)")
    parser.add_argument("--output", type=str, default=None,
                        help="Save full results to JSON file (optional)")
    parser.add_argument("--food-banks-only", action="store_true",
                        help="Skip restaurant analysis")
    args = parser.parse_args()

    radius = args.radius
    stops = VTA_STOPS
    print(f"\nVTA Bus Stop + Food Bank Proximity Finder")
    print(f"  Stops loaded   : {len(stops):,}")
    print(f"  Food banks     : {len(FOOD_BANKS)}")
    print(f"  Restaurants    : {len(RESTAURANTS)}")
    print(f"  Search radius  : {radius} miles")

    print(f"\nAnalyzing food banks...")
    fb_results = find_nearby_stops(FOOD_BANKS, stops, radius)

    rest_results = {}
    if not args.food_banks_only:
        print(f"Analyzing restaurants...")
        rest_results = find_nearby_stops(RESTAURANTS, stops, radius)

    print_report("FOOD BANKS", fb_results, radius)
    if rest_results:
        print_report("RESTAURANTS", rest_results, radius)

    if args.output:
        output = {"radius_miles": radius, "food_banks": fb_results}
        if rest_results:
            output["restaurants"] = rest_results
        with open(args.output, "w") as f:
            json.dump(output, f, indent=2)
        print(f"\n✅  Full results saved to: {args.output}")


if __name__ == "__main__":
    main()
